from functools import lru_cache

class Solution:
    def canWin(self, currentState: str) -> bool:
        @lru_cache(maxsize=None)
        def dfs(s: str) -> bool:
            for i in range(len(s) - 1):
                if s[i:i + 2] == '++' and not dfs(s[:i] + '--' + s[i + 2:]):
                    return True
            return False

        return dfs(currentState)

