class Solution {
    unordered_map<string, bool> memo;
public:
    bool canWin(string s) {
        auto it = memo.find(s);
        if (it != memo.end()) return it->second;
        bool res = false;
        for (int i = 0; i + 1 < (int)s.size(); i++) {
            if (s[i] == '+' && s[i + 1] == '+') {
                s[i] = s[i + 1] = '-';
                if (!canWin(s)) res = true;
                s[i] = s[i + 1] = '+';
                if (res) break;
            }
        }
        memo[s] = res;
        return res;
    }
};

