class Solution {
    private final Map<String, Boolean> memo = new HashMap<>();

    public boolean canWin(String currentState) {
        Boolean cached = memo.get(currentState);
        if (cached != null) return cached;
        boolean res = false;
        StringBuilder sb = new StringBuilder(currentState);
        for (int i = 0; i + 1 < sb.length(); i++) {
            if (sb.charAt(i) == '+' && sb.charAt(i + 1) == '+') {
                sb.setCharAt(i, '-');
                sb.setCharAt(i + 1, '-');
                if (!canWin(sb.toString())) res = true;
                sb.setCharAt(i, '+');
                sb.setCharAt(i + 1, '+');
                if (res) break;
            }
        }
        memo.put(currentState, res);
        return res;
    }
}

