class Solution {
public:
    bool canWin(string currentState) {
        vector<int> g(61, 0);
        for (int n = 2; n <= 60; n++) {
            unordered_set<int> seen;
            for (int i = 0; i <= n - 2; i++) seen.insert(g[i] ^ g[n - 2 - i]);
            int m = 0;
            while (seen.count(m)) m++;
            g[n] = m;
        }
        int acc = 0, run = 0;
        for (char c : currentState) {
            if (c == '+') run++;
            else { acc ^= g[run]; run = 0; }
        }
        acc ^= g[run];
        return acc != 0;
    }
};

